## Why This Is Asked
Tests knowledge of Trie data structures, deduplication strategies, and efficient prefix queries—essential skills for building autocomplete systems.

## Key Concepts
- Trie with per-node subtree counts for O(1) prefix counting
- Deduplication via global set to maintain word uniqueness
- Prefix-based retrieval with controlled result limits
- Lexicographic ordering through systematic child traversal

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.isWord = false;
    this.passCount = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
    this.wordSet = new Set();
  }

  insert(word) {
    if (this.wordSet.has(word)) return;
    this.wordSet.add(word);
    let node = this.root;
    for (const char of word) {
      if (!node.next.has(char)) {
        node.next.set(char, new TrieNode());
      }
      node = node.next.get(char);
      node.passCount++;
    }
    node.isWord = true;
  }

  countPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return 0;
      node = node.next.get(char);
    }
    return node.passCount;
  }

  listWithPrefix(prefix, limit) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return [];
      node = node.next.get(char);
    }
    const result = [];
    this.dfs(node, prefix, result, limit);
    return result;
  }

  dfs(node, current, result, limit) {
    if (result.length >= limit) return;
    if (node.isWord) {
      result.push(current);
    }
    const sortedKeys = Array.from(node.next.keys()).sort();
    for (const char of sortedKeys) {
      this.dfs(node.next.get(char), current + char, result, limit);
    }
  }
}
```

## Why This Is Asked
Tests knowledge of a practical data structure for real-world features (auto-complete) and how to extend it with per-word frequencies.

## Key Concepts
- Trie with terminal frequency tracking
- DFS/BFS to collect candidate words from a prefix
- Sorting by frequency then lexicographic order
- Edge cases: missing prefix, zero matches, tie handling

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.freq = 0; // frequency for word ending here
  }
}
class Trie {
  constructor() { this.root = new TrieNode(); }
  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.next.has(ch)) node.next.set(ch, new TrieNode());
      node = node.next.get(ch);
    }
    node.freq += 1;
  }
  autocomplete(prefix, K) {
    let node = this.root;
    for (const ch of prefix) {
      if (!node.next.has(ch)) return [];
      node = node.next.get(ch);
    }
    const results = [];
    const dfs = (n, path) => {
      if (n.freq > 0) results.push([path, n.freq]);
      for (const [ch, child] of n.next) dfs(child, path + ch);
    };
    dfs(node, prefix);
    results.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    return results.slice(0, K).map(v => v[0]);
  }
}
```

